{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kernen er korrekt: i særlige tilfælde, når art og grad ikke er tilstrækkeligt beskrevet, og ikke automatisk. Men svaret indeholder en juridisk fejl: «Hvis dokumentationen allerede beskriver dette klart nok, peger det imod behov for speciallægeerklæring; hvis ikke, peger det for…». Det er vendt om og modsiger kilden. Svaret siger også, at UDK «kun kan kræve» erklæringen, når dokumentationen er «for uklar eller utilstrækkelig». Kilden handler om at anmode, ikke kræve, og «kun» gør reglen udtømmende, hvilket ligner en væsentlig fejl i rubrikken. De fire eksempler mangler."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element er dækket: særlige tilfælde, art og grad ikke tilstrækkeligt beskrevet. Det andet er ikke dækket, da ingen af de fire eksempelgrupper nævnes (symptomintensitet/hyppighed, diskrepans, behandlingsmuligheder/prognose, daglig funktion versus ferie)."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvornår UDK kan bede om en speciallægeerklæring: i særlige tilfælde, når dokumentationen ikke i tilstrækkelig grad beskriver art og grad. Det indeholder noget fyldtekst, men svarer på spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, vejledning nr. 10157 af 5. oktober 2026, og dens udsagn om speciallægeerklæring. Der er ikke angivet afsnitsnummer, men vejledningen kan identificeres."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Den angivne vejledning VEJ nr. 10157 af 05/10/2026 findes i det frosne materiale. Den er aktuel og autoritativ, og afsnit 5.1.3.2 er relevant."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Hovedpåstanden støttes af afsnit 5.1.3.2. Flere påstande støttes ikke eller er forkerte i forhold til kilden. Det gælder «kun kan kræve» og den omvendte logik om, at klar dokumentation peger imod en erklæring, mens uklar dokumentation peger for. Desuden bygger svaret på at «håndtering af handicaptillæg handler om nødvendig dokumentation». Den kilde, der er vist, dækker ikke det udsagn fuldt ud."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en udtømmende betingelse: UDK «kun» kan kræve erklæringen, når dokumentationen er for uklar eller utilstrækkelig. Det understøttes ikke af materialet, hvor eksemplerne er illustrative («f.eks.»). Svaret omtaler også «kræve», som kilden ikke bruger."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "«I særlige tilfælde» og ikke-automatik er bevaret. Svaret gengiver ikke, at eksemplerne er illustrative og alternative, og «stor tvivl» er ikke gengivet. Svaret gør i stedet udgangspunktet til en «kun»-regel."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt inkonsistent. Afsnittet «Nærmere afgrænsning» siger, at klar dokumentation «peger imod» en speciallægeerklæring, men formuleringen er forvirrende og vendt om. Det passer ikke med den øvrige logik om, at uklar dokumentation giver mulighed for at anmode."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger «kan» korrekt flere steder. Men «kun kan kræve» gør en mulighed til en udtømmende og stærkere regel. Kilden siger, at UDK kan anmode, og at UDK anmoder, hvis dokumentationen ikke er tilstrækkelig. Det er ikke det samme som «kræve»."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret dækker hovedreglen: «i særlige tilfælde» og når dokumentationen ikke i tilstrækkelig grad beskriver art og grad. Det udelader alle fire eksempler på situationer og udgiftsdækningen. Det tilføjer en «kun»-formulering og en omvendt logik."
    }
  },
  "overall_notes": "Svaret har den centrale hovedregel rigtig, men er ufuldstændigt, fordi de fire eksempelgrupper mangler. Det indeholder også en modalitetsfejl («kun kan kræve») og en uklar og omvendt formulering i afsnittet «Nærmere afgrænsning». Kildehenvisningen er identificerbar og gyldig, men støtter ikke alle påstande."
}

